import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// The init options src/panel.ts hands to the Go program in each role, with the wasm replaced by a recorder (the real Go side
// of these options is tested in cmd/mistgate-edge). The dist files are generated by scripts/build-edge.ps1 and may not exist.
vi.mock("../dist/wasm_exec.js", () => ({}));
vi.mock("../dist/panel.wasm", () => ({ default: {} }));

type Options = Record<string, any>;
let initCalls: Options[];

beforeEach(() => {
  vi.resetModules();
  initCalls = [];
  const panel = { init: vi.fn(async (options: Options) => void initCalls.push(options)) };
  (globalThis as any).Go = class {
    importObject = {};
    run() {
      (globalThis as any).mgPanel = panel;
      return new Promise<void>(() => {}); // the Go program never returns
    }
  };
  vi.spyOn(WebAssembly, "instantiate").mockResolvedValue({} as any);
});

afterEach(() => {
  vi.restoreAllMocks();
  delete (globalThis as any).Go;
  delete (globalThis as any).mgPanel;
});

const namespace = (calls: string[] = []) =>
  ({
    idFromName: (name: string) => name,
    get: (id: string) => ({ kick: async () => void calls.push(`kick ${id}`), ask: async () => null, close: async () => {}, poke: async () => {} }),
  }) as any;

describe("getPanel (the main Worker)", () => {
  const env = (extra: Options = {}) => ({ DB: {}, MASTER_KEY: "ab".repeat(32), ASSETS: {}, LIMITER: namespace(), NODELINK: namespace(), ...extra }) as any;

  it("forwards SSH installs to the Provisioner and can wake it when the binding exists", async () => {
    const kicks: string[] = [];
    const { getPanel } = await import("../src/panel");
    await getPanel(env({ PROVISIONER: namespace(kicks) }), "https://example.com");
    const { provision } = initCalls[0]!;
    expect(provision.role).toBe("forward");
    expect(provision.sshConnect).toBeUndefined();
    await provision.kick();
    expect(kicks).toEqual(["kick provisioner"]);
  });

  it("says nothing about the Provisioner when the binding is missing (the Worker answers 503 itself)", async () => {
    const { getPanel } = await import("../src/panel");
    await getPanel(env(), "https://example.com");
    expect(initCalls[0]!.provision).toBeUndefined();
    expect(initCalls[0]!.assets).toBeTypeOf("function");
  });
});

describe("getServePanel (the Provisioner's script)", () => {
  const env = () => ({ DB: { db: true }, MASTER_KEY: "cd".repeat(32), LIMITER: namespace(), NODELINK: namespace(), PROVISIONER: namespace() }) as any;

  it("serves the instance the main Worker made: no assets, no public URL, no setup token, with its sockets and its kick", async () => {
    const hooks = { kick: vi.fn(async () => {}), sshConnect: vi.fn(async () => ({ ok: false })) };
    const { getServePanel } = await import("../src/panel");
    const e = env();
    await getServePanel(e, hooks);
    const options = initCalls[0]!;
    expect(options.provision).toEqual({ role: "serve", kick: hooks.kick, sshConnect: hooks.sshConnect });
    expect(options.d1).toBe(e.DB);
    expect(options.masterKey).toBe(e.MASTER_KEY);
    for (const absent of ["assets", "publicURL", "adminHost", "adminPrefix", "subPrefix", "setupTokenSHA256"]) expect(options).not.toHaveProperty(absent);
    expect(options.limit).toBeTypeOf("function");
    expect(options.nodeLink.ask).toBeTypeOf("function");
    expect(options.nodeLink.send).toBeTypeOf("function");
  });

  it("initialises Go once for concurrent callers", async () => {
    const hooks = { kick: async () => {}, sshConnect: async () => ({}) };
    const { getServePanel } = await import("../src/panel");
    await Promise.all([getServePanel(env(), hooks), getServePanel(env(), hooks)]);
    expect(initCalls).toHaveLength(1);
  });
});
